        "question": "Write a program using nested if to calculate income tax with deductions. First validate income, then apply deductions, then calculate tax based on slabs.",
        "solution": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        System.out.print(\"Enter annual income: \");\n        double income = sc.nextDouble();\n        System.out.print(\"Enter deductions: \");\n        double deductions = sc.nextDouble();\n        double taxableIncome, tax = 0;\n        if (income > 0) {\n            if (deductions < income) {\n                taxableIncome = income - deductions;\n            } else {\n                taxableIncome = 0;\n            }\n            System.out.println(\"Taxable Income: Rs \" + taxableIncome);\n            if (taxableIncome > 0) {\n                if (taxableIncome <= 250000) {\n                    tax = 0;\n                } else if (taxableIncome <= 500000) {\n                    tax = (taxableIncome - 250000) * 0.05;\n                } else if (taxableIncome <= 1000000) {\n                    tax = 250000 * 0.05 + (taxableIncome - 500000) * 0.2;\n                } else {\n                    tax = 250000 * 0.05 + 500000 * 0.2 + (taxableIncome - 1000000) * 0.3;\n                }\n                System.out.println(\"Tax: Rs \" + tax);\n            } else {\n                System.out.println(\"No tax due to deductions.\");\n            }\n        } else {\n            System.out.println(\"Invalid income.\");\n        }\n        sc.close();\n    }\n}",
