        "question": "Write a program using nested if to implement a menu-driven shape area calculator. Main menu: 1. Circle, 2. Rectangle, 3. Triangle. Sub-menu for each shape.",
        "solution": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        System.out.println(\"--- SHAPE AREA CALCULATOR ---\");\n        System.out.println(\"1. Circle\");\n        System.out.println(\"2. Rectangle\");\n        System.out.println(\"3. Triangle\");\n        System.out.print(\"Enter your choice: \");\n        int choice = sc.nextInt();\n        if (choice == 1) {\n            System.out.print(\"Enter radius: \");\n            double r = sc.nextDouble();\n            System.out.println(\"Area of Circle: \" + (3.14 * r * r));\n        } else if (choice == 2) {\n            System.out.print(\"Enter length: \");\n            double l = sc.nextDouble();\n            System.out.print(\"Enter breadth: \");\n            double b = sc.nextDouble();\n            System.out.println(\"Area of Rectangle: \" + (l * b));\n        } else if (choice == 3) {\n            System.out.println(\"Triangle type:\");\n            System.out.println(\"1. Right-angled\");\n            System.out.println(\"2. Equilateral\");\n            System.out.print(\"Enter choice: \");\n            int subChoice = sc.nextInt();\n            if (subChoice == 1) {\n                System.out.print(\"Enter base: \");\n                double base = sc.nextDouble();\n                System.out.print(\"Enter height: \");\n                double height = sc.nextDouble();\n                System.out.println(\"Area: \" + (0.5 * base * height));\n            } else if (subChoice == 2) {\n                System.out.print(\"Enter side: \");\n                double side = sc.nextDouble();\n                double area = (Math.sqrt(3) / 4) * side * side;\n                System.out.println(\"Area: \" + area);\n            } else {\n                System.out.println(\"Invalid sub-choice.\");\n            }\n        } else {\n            System.out.println(\"Invalid main choice.\");\n        }\n        sc.close();\n    }\n}",
