        "id": "nif-pg-m-6",
        "question": "Write a program using nested if to implement an e-commerce discount system. Check stock, then order amount, then membership/coupon.",
        "solution": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        System.out.print(\"Is item in stock? (true/false): \");\n        boolean inStock = sc.nextBoolean();\n        System.out.print(\"Enter order amount: \");\n        double amount = sc.nextDouble();\n        System.out.print(\"Is premium member? (true/false): \");\n        boolean premium = sc.nextBoolean();\n        if (inStock) {\n            System.out.println(\"Item available.\");\n            if (amount >= 1000) {\n                System.out.println(\"Eligible for discount.\");\n                if (premium) {\n                    amount = amount * 0.75;\n                    System.out.println(\"Premium discount: 25% off.\");\n                } else {\n                    amount = amount * 0.90;\n                    System.out.println(\"Standard discount: 10% off.\");\n                }\n            } else {\n                System.out.println(\"No discount (min order Rs 1000).\");\n            }\n            System.out.println(\"Final amount: Rs \" + amount);\n        } else {\n            System.out.println(\"Item out of stock.\");\n        }\n        sc.close();\n    }\n}",
        "output": "Is item in stock? (true/false): true\\nEnter order amount: 2000\\nIs premium member? (true/false): false\\nItem available.\\nEligible for discount.\\nStandard discount: 10% off.\\nFinal amount: Rs 1800.0"
