        "id": "sw-pg-h-4",
        "question": "Write a program using switch to implement a complete movie ticket booking system.",
        "solution": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        System.out.println('1.Morning(150) 2.Matinee(200) 3.Evening(300) 4.Night(350)');\n        System.out.print('Show: '); int show = sc.nextInt();\n        System.out.println('1.Standard 2.Premium 3.Recliner');\n        System.out.print('Seat: '); int seat = sc.nextInt();\n        System.out.print('Tickets: '); int t = sc.nextInt();\n        double base = 0, total = 0;\n        switch (show) { case 1: base = 150; break; case 2: base = 200; break; case 3: base = 300; break; case 4: base = 350; break; }\n        switch (seat) { case 1: total = base*t; break; case 2: total = base*1.5*t; break; case 3: total = base*2.5*t; break; }\n        if (t >= 4) total *= 0.9;\n        System.out.println('Total: Rs ' + total);\n        sc.close();\n    }\n}",
        "output": "1.Morning(150) 2.Matinee(200) 3.Evening(300) 4.Night(350)\nShow: 3\n1.Standard 2.Premium 3.Recliner\nSeat: 2\nTickets: 2\nTotal: Rs 900.0"
