        "solution": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        System.out.println('1.Basic(1000) 2.Standard(2000) 3.Premium(3500)');\n        System.out.print('Plan: '); int plan = sc.nextInt();\n        System.out.print('Months: '); int months = sc.nextInt();\n        double monthly = 0, total = 0;\n        switch (plan) { case 1: monthly = 1000; break; case 2: monthly = 2000; break; case 3: monthly = 3500; break; }\n        total = monthly * months;\n        switch (months) { case 12: total *= 0.75; break; case 6: total *= 0.85; break; case 3: total *= 0.90; break; }\n        System.out.println('Total: Rs ' + total);\n        sc.close();\n    }\n}",
