        "question": "Write a program using switch to implement a complete library management system with fines.",
        "solution": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        System.out.println('1.Student 2.Faculty 3.General');\n        System.out.print('Member: '); int mem = sc.nextInt();\n        System.out.print('Days late: '); int days = sc.nextInt();\n        double fee = 0, fine = 0;\n        switch (mem) { case 1: fee = 100; fine = days * 5; break; case 2: fee = 200; fine = days * 10; break; case 3: fee = 300; fine = days * 8; break; }\n        if (days > 30) fine += 50;\n        System.out.println('Fee: ' + fee + ' Fine: ' + fine + ' Total: ' + (fee + fine));\n        sc.close();\n    }\n}",
