      "title": "Complete Tax Calculator with All Deductions",
      "question": "Create a comprehensive tax calculator that handles: salary income, business income, capital gains, 80C deductions, 80D medical insurance, HRA exemption, and calculates tax with rebate under section 87A.",
      "solution": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        System.out.print(\"Salary income: \"); double salary = sc.nextDouble();\n        System.out.print(\"Business income: \"); double business = sc.nextDouble();\n        System.out.print(\"Capital gains: \"); double gains = sc.nextDouble();\n        System.out.print(\"HRA received: \"); double hraRec = sc.nextDouble();\n        System.out.print(\"Rent paid: \"); double rent = sc.nextDouble();\n        System.out.print(\"80C investments: \"); double inv80C = sc.nextDouble();\n        System.out.print(\"80D medical: \"); double med80D = sc.nextDouble();\n        double grossTotal = salary + business + gains;\n        double hraExempt = Math.min(hraRec, Math.min(rent - salary * 0.1, salary * 0.5));\n        double ded80C = Math.min(inv80C, 150000);\n        double ded80D = Math.min(med80D, 25000);\n        double totalDed = hraExempt + ded80C + ded80D;\n        double taxable = Math.max(0, grossTotal - totalDed);\n        double tax = 0, rebate = 0;\n        System.out.println(\"\\n--- TAX COMPUTATION ---\");\n        System.out.println(\"Gross Total: Rs \" + grossTotal);\n        System.out.println(\"Total Deductions: Rs \" + totalDed);\n        System.out.println(\"Taxable Income: Rs \" + taxable);\n        if (taxable > 0) {\n            if (taxable <= 250000) tax = 0;\n            else if (taxable <= 500000) { tax = (taxable - 250000) * 0.05; rebate = Math.min(tax, 12500); }\n            else if (taxable <= 1000000) tax = 12500 + (taxable - 500000) * 0.2;\n            else tax = 12500 + 100000 + (taxable - 1000000) * 0.3;\n            tax = Math.max(0, tax - rebate);\n            System.out.println(\"Tax: Rs \" + tax);\n        }\n        sc.close();\n    }\n}",
