      "question": "Design a 5-level hospital triage system: Level 1 (Life-threatening), Level 2 (Emergency), Level 3 (Urgent), Level 4 (Semi-urgent), Level 5 (Non-urgent). Each level has specific criteria and response protocols.",
      "solution": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        System.out.print(\"Is patient breathing? (true/false): \");\n        boolean breathing = sc.nextBoolean();\n        System.out.print(\"Heart rate: \");\n        int heartRate = sc.nextInt();\n        System.out.print(\"Blood pressure systolic: \");\n        int bp = sc.nextInt();\n        System.out.print(\"Pain level (1-10): \");\n        int pain = sc.nextInt();\n        System.out.print(\"Age: \");\n        int age = sc.nextInt();\n        System.out.println(\"\\n--- TRIAGE ASSESSMENT ---\");\n        if (!breathing || heartRate < 30 || heartRate > 200) {\n            System.out.println(\"LEVEL 1: LIFE-THREATENING\");\n            System.out.println(\"Response: Immediate CPR/Defibrillation\");\n            System.out.println(\"Target: < 2 minutes\");\n        } else if (bp < 60 || bp > 220 || pain >= 9) {\n            System.out.println(\"LEVEL 2: EMERGENCY\");\n            System.out.println(\"Response: Rapid assessment & intervention\");\n            System.out.println(\"Target: < 10 minutes\");\n            if (age >= 65) System.out.println(\"Note: Geriatric protocol activated\");\n        } else if (pain >= 7 || (bp > 180 && age > 60)) {\n            System.out.println(\"LEVEL 3: URGENT\");\n            System.out.println(\"Response: Prompt medical evaluation\");\n            System.out.println(\"Target: < 30 minutes\");\n        } else if (pain >= 4 || heartRate > 100) {\n            System.out.println(\"LEVEL 4: SEMI-URGENT\");\n            System.out.println(\"Response: Standard evaluation\");\n            System.out.println(\"Target: < 60 minutes\");\n        } else {\n            System.out.println(\"LEVEL 5: NON-URGENT\");\n            System.out.println(\"Response: Routine checkup\");\n            System.out.println(\"Target: < 120 minutes\");\n        }\n        sc.close();\n    }\n}",
