      "id": "nif-cp-8",
      "title": "Complete Restaurant Management System",
      "question": "Create a restaurant management system with: table reservation, menu ordering, kitchen order tracking, bill generation with taxes, and payment processing.",
      "solution": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        System.out.println(\"--- RESTAURANT MANAGEMENT ---\");\n        System.out.print(\"Number of guests: \");\n        int guests = sc.nextInt();\n        System.out.print(\"Table type (1.Standard 2.Premium 3.Private): \");\n        int tableType = sc.nextInt();\n        double tableCharge = 0;\n        if (tableType == 1) tableCharge = 0;\n        else if (tableType == 2) tableCharge = 500;\n        else tableCharge = 1500;\n        double orderTotal = 0;\n        System.out.println(\"\\n--- MENU ---\");\n        System.out.println(\"1. Veg Thali (Rs 250)\");\n        System.out.println(\"2. Non-Veg Thali (Rs 350)\");\n        System.out.println(\"3. Pizza (Rs 400)\");\n        System.out.println(\"4. Biryani (Rs 300)\");\n        System.out.print(\"Choose item: \");\n        int item = sc.nextInt();\n        System.out.print(\"Quantity: \");\n        int qty = sc.nextInt();\n        if (item == 1) orderTotal = 250 * qty;\n        else if (item == 2) orderTotal = 350 * qty;\n        else if (item == 3) orderTotal = 400 * qty;\n        else if (item == 4) orderTotal = 300 * qty;\n        System.out.println(\"\\n--- BILL ---\");\n        System.out.println(\"Table charge: Rs \" + tableCharge);\n        System.out.println(\"Order amount: Rs \" + orderTotal);\n        double subtotal = tableCharge + orderTotal;\n        double cgst = subtotal * 0.025;\n        double sgst = subtotal * 0.025;\n        double serviceCharge = subtotal * 0.10;\n        double total = subtotal + cgst + sgst + serviceCharge;\n        System.out.println(\"Subtotal: Rs \" + subtotal);\n        System.out.println(\"CGST (2.5%): Rs \" + cgst);\n        System.out.println(\"SGST (2.5%): Rs \" + sgst);\n        System.out.println(\"Service charge (10%): Rs \" + serviceCharge);\n        System.out.println(\"Total: Rs \" + total);\n        if (guests >= 6) {\n            double groupDiscount = total * 0.10;\n            total -= groupDiscount;\n            System.out.println(\"Group discount (10%): Rs \" + groupDiscount);\n            System.out.println(\"Final amount: Rs \" + total);\n        }\n        sc.close();\n    }\n}",
      "output": "--- RESTAURANT MANAGEMENT ---\\nNumber of guests: 4\\nTable type (1.Standard 2.Premium 3.Private): 2\\n\\n--- MENU ---\\n1. Veg Thali (Rs 250)\\n2. Non-Veg Thali (Rs 350)\\n3. Pizza (Rs 400)\\n4. Biryani (Rs 300)\\nChoose item: 3\\nQuantity: 2\\n\\n--- BILL ---\\nTable charge: Rs 500\\nOrder amount: Rs 800\\nSubtotal: Rs 1300\\nTotal: Rs 1430"
